import urllib.request
import json

url = "https://planetarycomputer.microsoft.com/api/stac/v1/search"
params = {
    "collections": ["esa-worldcover"],
    "bbox": [76.9157258, 10.2879931, 76.9957258, 10.3679931]
}

req = urllib.request.Request(
    url,
    data=json.dumps(params).encode('utf-8'),
    headers={'Content-Type': 'application/json', 'User-Agent': 'Mozilla/5.0'}
)

print("Querying Planetary Computer STAC API...")
try:
    with urllib.request.urlopen(req) as response:
        res = json.loads(response.read().decode())
        print(f"Number of items found: {len(res.get('features', []))}")
        for feature in res.get('features', []):
            print(f"ID: {feature['id']}, BBox: {feature['bbox']}")
            print(f"Map asset URL: {feature['assets']['map']['href']}")
except Exception as e:
    print(f"Error: {e}")

